/**
 * Implicit long convolutions (Hyena). A filter as long as the sequence is not stored tap by tap; it is generated by a
 * small feed-forward network of the position, $h_t = w(t) \cdot \mathrm{FFN}(\mathrm{PE}(t))$, where PE is a truncated
 * complex exponential basis, the FFN uses sine activations and $w(t) = e^{-\alpha t/L} + b$ is a decaying window. The
 * Hyena operator of order $N$ alternates long causal convolutions with elementwise gates:
 * $\zvec^1 = \vvec$, $\zvec^{n+1} = \xvec^n \odot (\hvec^n * \zvec^n)$, $\yvec = \zvec^{N+1}$. The convolutions run
 * by FFT (`causalConvolution` with `method: 'fft'`), $O(L \log L)$ per filter, against the direct $O(L^2)$ sum.
 *
 * Source: Poli, Massaroli, Nguyen, Fu, Dao, Baccus, Bengio, Ermon and Ré (2023), "Hyena Hierarchy: Towards Larger
 * Convolutional Language Models", Definition 3.1 (the operator), §3.3 eq. (7) (the implicit filter and window) and
 * Appendix D.3 (the positional encoding $\rho_k(t) = e^{i2\pi kt/L}$). Differences: the window here is
 * $e^{-\alpha t/L} + b$ with $t/L \in [0, 1)$ and one decay per filter, where the paper varies $\alpha$ across
 * channels; the FFN weights are drawn, not trained.
 */

import type { Size } from 'aifn-compute/foundation/contracts'
import { normals, type Stream } from 'aifn-compute/foundation/random'
import {
  add,
  fromData,
  matmul,
  mul,
  shapeOfValue,
  sin,
  slice,
  stack,
  toFlat,
  type Tensor,
  type Value,
} from 'aifn-compute/foundation/tensor'
import { causalConvolution } from './ssm'

/**
 * The positional encoding of Hyena's filter network for positions $t = 0, \dots, L - 1$: row $t$ holds $t/L$, then
 * $\operatorname{Re}\rho_k(t) = \cos(2\pi kt/L)$ for $k = 0, \dots, K - 1$, then
 * $\operatorname{Im}\rho_k(t) = \sin(2\pi kt/L)$, with $\rho_k(t) = e^{i2\pi kt/L}$.
 *
 * @param length The number of positions $L$.
 * @param features The number of complex exponentials $K$.
 * @returns The encoding, $L \times (2K + 1)$.
 *
 * @example Eight positions, three exponentials
 * print('PE =', hyenaPositionalEncoding(8, 3))
 */
export function hyenaPositionalEncoding(length: Size, features: Size): Tensor {
  const width = 2 * features + 1
  const out = new Float64Array(length * width)
  for (let t = 0; t < length; t++) {
    out[t * width] = t / length
    for (let k = 0; k < features; k++) {
      out[t * width + 1 + k] = Math.cos((2 * Math.PI * k * t) / length)
      out[t * width + 1 + features + k] = Math.sin((2 * Math.PI * k * t) / length)
    }
  }
  return fromData(out, [length, width])
}

/** Options of `implicitFilter`. */
export type ImplicitFilterOptions = {
  /** The number of complex exponential features $K$ (the encoding has $2K + 1$ columns). */
  features: Size
  /** The width of the hidden layers. */
  width: Size
  /** The number of hidden layers (each a linear map, then $\sin(\omega\,\cdot)$). */
  depth: Size
  /** The frequency $\omega$ of the sine activations. */
  frequency: number
  /** The decay rate $\alpha$ of the window $e^{-\alpha t/L}$. */
  decay: number
  /** The constant $b$ added to the window, so the filter is not forced to zero at long lags. */
  bias: number
}

/**
 * One implicit filter of length $L$: an FFN with sine activations applied to the positional encoding, times the window
 * $w(t) = e^{-\alpha t/L} + b$. The weights are drawn from `s` with variance $1/\text{fan-in}$, layer by layer
 * (weights, then biases), then the output column, so a seed fixes the filter.
 *
 * @param length The filter length $L$.
 * @param options The encoding, network and window settings.
 * @param s The stream the weights are drawn from; it advances.
 * @returns The `filter` $h_t = w(t)\,\mathrm{FFN}(\mathrm{PE}(t))$, the network's `raw` output and the `window`, each
 *   $L$ values.
 *
 * @example A 64-tap filter decaying over its length
 * const options = { features: 4, width: 16, depth: 2, frequency: 10, decay: 6, bias: 0.01 }
 * const { filter, window } = implicitFilter(64, options, stream(1))
 * print('window at 0, 32, 63 =', [get(window, 0), get(window, 32), get(window, 63)])
 * print('first taps =', slice(filter, [0, 5]))
 */
export function implicitFilter(
  length: Size,
  options: ImplicitFilterOptions,
  s: Stream,
): { filter: Tensor; raw: Tensor; window: Tensor } {
  let h: Value = hyenaPositionalEncoding(length, options.features)
  let fanIn = 2 * options.features + 1
  for (let layer = 0; layer < options.depth; layer++) {
    const W = mul(normals(s, [fanIn, options.width]), 1 / Math.sqrt(fanIn))
    const b = normals(s, [options.width])
    h = sin(mul(add(matmul(h, W), b), options.frequency))
    fanIn = options.width
  }
  const out = mul(normals(s, [fanIn, 1]), 1 / Math.sqrt(fanIn))
  const raw = toFlat(matmul(h, out) as Tensor)
  const window = raw.map((_, t) => Math.exp((-options.decay * t) / length) + options.bias)
  const filter = raw.map((v, t) => v * window[t])
  const vector = (x: number[]) => fromData(Float64Array.from(x), [length])
  return { filter: vector(filter), raw: vector(raw), window: vector(window) }
}

/**
 * The Hyena operator of order $N$: $\zvec^1 = \vvec$, $\zvec^{n+1} = \xvec^n \odot (\hvec^n * \zvec^n)$ with each
 * causal convolution by FFT, and $\yvec = \zvec^{N+1}$. Differentiable in every argument.
 *
 * @param v The input $\vvec$, a vector of $L$.
 * @param gates The gates $\xvec^1, \dots, \xvec^N$, $N \times L$.
 * @param filters The filters $\hvec^1, \dots, \hvec^N$, $N \times L_h$ (taps past $L$ are unused).
 * @returns Every $\zvec$, $(N + 1) \times L$: row 0 is $\vvec$ and row $N$ the output $\yvec$.
 *
 * @example Order two by hand
 * const gates = tensor([[1, 0, 1, 1], [0.5, 1, 1, 2]])
 * const filters = tensor([[1, 0.5, 0.25, 0], [1, -1, 0, 0]])
 * print('z =', hyenaOperator(tensor([1, 2, 0, -1]), gates, filters))
 */
export function hyenaOperator(v: Value, gates: Value, filters: Value): Value {
  const N = shapeOfValue(filters)[0]
  const z: Value[] = [v]
  for (let n = 0; n < N; n++) {
    const conv = causalConvolution(slice(filters, n), z[n], { method: 'fft' })
    z.push(mul(slice(gates, n), conv))
  }
  return stack(z, 0)
}
